"""Modul „Forster im Klub“: Forsters Eintritt in den Mainzer Klub (5. November 1792), die zwei Bücher (6. November)
und seine Rede „Ueber das Verhältniß der Mainzer gegen die Franken“, mit Anton Hoffmanns Bericht darüber.

Quellen:
- Die Rede: G. Forster, Sämmtliche Schriften, Bd. 6 (Leipzig 1843), S. 413–431. Transkription am Seitenbild in
  tools/forster-1792-rede.txt (Seitenmarken [nnn]); Internet Archive smmtlicheschri06forsuoft, Bild n = Seite + 11.
- [Anton Hoffmann], Darstellung der Mainzer Revolution, Heft 3 (1793), S. 222–234, und Heft 4 (1793), S. 256–260;
  Bayerische Staatsbibliothek bsb10421484 (Bild = Seite − 158) und bsb10421485 (Bild = Seite − 242).
Schreibung der Drucke; ſ als s; Kustoden weggelassen; Silbentrennung am Zeilen- und Seitenende aufgelöst.
"""
import json
import re
from pathlib import Path

HERE = Path(__file__).resolve().parent
OUT = HERE.parent / "data" / "forster1792.json"


def u(n, pg, titel, titel_en, orig, en, note="", note_en=""):
    d = {"n": n, "pg": pg, "titel": titel, "titel_en": titel_en, "orig": orig.strip(), "en": en.strip()}
    if note:
        d["note"], d["note_en"] = note, note_en
    return d


# ------------------------------------------------------------------ the speech, from the transcription file
def speech_paragraphs():
    t = (HERE / "forster-1792-rede.txt").read_text(encoding="utf-8").split("\n", 2)[2]
    t = re.sub(r"-\[(\d+)\]", r"⟨\1⟩", t)
    t = re.sub(r"-\n\[(\d+)\] ", r"⟨\1⟩", t)
    t = re.sub(r"\n\[(\d+)\] (?=[a-zäöü]|Euch von|Hände;)", r" ⟨\1⟩", t)
    t = re.sub(r" \[(\d+)\] ", r" ⟨\1⟩", t)
    t = re.sub(r"^\[(\d+)\] ", r"⟨\1⟩", t, flags=re.M)
    return [p for p in t.split("\n") if p.strip()]


def group(paras, starts):
    """Cut the paragraph list at the given opening words; return [(text, 'first–last page')]."""
    idx = [next(i for i, p in enumerate(paras) if re.sub(r"⟨\d+⟩", "", p).startswith(s)) for s in starts] + [len(paras)]
    page, out = 413, []
    for a, b in zip(idx, idx[1:]):
        chunk = "\n".join(paras[a:b])
        first = int(re.match(r"⟨(\d+)⟩", chunk).group(1)) if chunk.startswith("⟨") else page
        marks = [int(m) for m in re.findall(r"⟨(\d+)⟩", chunk)]
        last = marks[-1] if marks else first
        page = last
        out.append((re.sub(r"⟨\d+⟩", "", chunk), f"SS VI, {first}" + (f"–{last}" if last != first else "")))
    return out


